"""Stage and describe the frozen v2 analysis; never rerun trajectory computation."""
from pathlib import Path
import json, hashlib, shutil
import pandas as pd

def stage(out):
    snap=out/'grafted_snapshot'; data=out/'supplementary_data'
    for item in json.loads((snap/'snapshot_manifest.json').read_text()):
        assert hashlib.sha256((snap/item['snapshot']).read_bytes()).hexdigest()==item['sha256']
    d=pd.read_csv(snap/'grafted_segment_rmsd_summary_v2.csv')
    controls=pd.read_csv(snap/'resolved_loop_control_rmsd.csv')
    logs=pd.read_csv(snap/'grafted_segment_run_log_v2.csv')
    recovered=json.loads((snap/'grafted_segments_recovered_v2.json').read_text())
    systems={s['system_id']:s for s in recovered}
    assert len(d)==938 and d.system_id.nunique()==205 and d.n_frames.eq(225).all()
    fit_scope=[]; fit_n=[]
    for _,r in d.iterrows():
        s=systems[r.system_id]; c=s['chains'][int(r.chain_index)]
        seg=next(x for x in s['segments'] if x['chain_index']==r.chain_index and int(x['sim_resid_start'])==r.sim_resid_start and int(x['sim_resid_end'])==r.sim_resid_end)
        for k in ['length','rmsd_mean','selffit_rmsd_mean']:assert float(seg[k])==float(r[k])
        n=c['length']-c['n_grafted_residues'];fallback=n<10
        fit_scope.append('global_resolved_core' if fallback else 'same_chain_resolved_core')
        fit_n.append(sum(x['length']-x['n_grafted_residues'] for x in s['chains']) if fallback else n)
    d['replica']=1;d['fit_scope']=fit_scope;d['n_fit_ca']=fit_n
    d['self_fit_low_atom_flag']=d.length.lt(3)
    d['match_ratio_ge_0p9']=d.match_ratio.ge(.9)
    assert d.fit_scope.eq('global_resolved_core').sum()==6
    short=d[d.location.eq('loop')&d.length.le(20)]
    assert len(short)==437 and short.rmsd_mean.le(3).sum()==125
    sensitivity=[]
    selections={'all_inferred_segments':d,'match_ratio_ge_0p9':d[d.match_ratio.ge(.9)],'exclude_Gq_8F7X_chain_0':d[~(d.system_id.eq('Gq_8F7X')&d.chain_index.eq(0))]}
    for label,sub in selections.items():
        loops=sub[sub.location.eq('loop')&sub.length.le(20)]
        sensitivity.append(dict(selection=label,n_segments=len(sub),n_systems=sub.system_id.nunique(),n_short_loops=len(loops),short_loop_scaffold_median_A=loops.rmsd_mean.median(),short_loop_n_le_3A=int(loops.rmsd_mean.le(3).sum()),short_loop_fraction_le_3A=loops.rmsd_mean.le(3).mean(),short_loop_self_fit_median_A=loops.selffit_rmsd_mean.median(),short_loop_self_fit_median_ge_3res_A=loops.loc[loops.length.ge(3),'selffit_rmsd_mean'].median()))
    sensitivity=pd.DataFrame(sensitivity)
    numbers={'n_segments':len(d),'n_systems_with_segments':d.system_id.nunique(),'n_systems_processed':len(logs),'n_inferred_mask_residues':int(logs.n_grafted_residues.sum()),'n_segment_residues':int(d.length.sum()),'n_excluded_singletons':int(logs.n_grafted_residues.sum()-d.length.sum()),'n_short_loops':len(short),'short_loop_scaffold_median_A':float(short.rmsd_mean.median()),'n_short_loops_le_3A':int(short.rmsd_mean.le(3).sum()),'short_loop_self_fit_median_A':float(short.selffit_rmsd_mean.median()),'n_short_loops_2res':int(short.length.eq(2).sum()),'short_loop_self_fit_median_ge_3res_A':float(short.loc[short.length.ge(3),'selffit_rmsd_mean'].median()),'n_controls':len(controls),'control_scaffold_median_A':float(controls.rmsd_mean.median()),'n_controls_le_3A':int(controls.rmsd_mean.le(3).sum()),'n_global_fit_segments':6,'sensitivity':sensitivity.to_dict('records')}
    readme='''# Supplementary Data S8 — retrospectively inferred modeled segments

Primary table: 938 segments across 205 of 207 systems, replica 1 only. The complete unfiltered v2 population is used for all primary statistics. The frozen original CSV/JSON, computation scripts and checksum manifest are in revision_package/grafted_snapshot; they are preserved unchanged. Segment positions use the released PDB residue numbering and zero-based inferred chain_index, not source-PDB numbering.

Segments were inferred by difflib sequence comparison against experimentally resolved source-PDB chains, with autojunk disabled. The implemented mapping uses all exact matching blocks (not a minimum three-residue block); uncovered runs separated by up to three matched residues are merged, and isolated singletons are excluded. The 34,962-residue inferred mask includes 290 excluded singletons; the 938 analyzed segments contain 34,672 residues. Merged runs can include experimentally matched bridging residues. This is a retrospective comparison, not a manual graft log or proof of AlphaFold provenance. Construct changes, mutations, tags and use of GPCRdb-refined starting structures can affect identification.

RMSDs are in Å. Scaffold-fit RMSD uses resolved Cα atoms of the same chain when at least ten exist; six segments use the global resolved core. fit_scope and n_fit_ca document this choice. Self-fit RMSD removes each segment's rigid-body displacement. self_fit_low_atom_flag identifies two-residue segments, whose self-fit RMSD provides very limited information about conformation. The original self-fit values are retained for provenance. Neither metric proves experimental accuracy or absence of drift.

The analysis samples 225 replica-1 frames at 2-ns intervals from nominal 50 to 498 ns, relative to the production-start structure. The fixed 50-ns exclusion is descriptive and does not follow the system-specific S7 stationarity recommendation. No new PBC rejection or trend test was implemented in this v2 protocol. The script's header overstates removal of interdomain motion: fitting a chain removes overall chain motion but retains intrachain domain movement.

match_ratio is the difflib similarity ratio 2M/(N_sim+N_exp), not sequence identity among resolved residues. Added missing regions lower it even when resolved residues match perfectly. Gq_8F7X chain_index 0 has 351 simulated and 221 resolved residues; matching all 221 yields 0.773. It remains in the primary table. A blanket >=0.9 filter would retain 296/938 segments and substantially change the population. Sensitivity CSV/XLSX gives both that subset and the proposed exclusion of this chain, each with its own counts and summaries; neither replaces the full-population result. The inherited n_mutations column is a count of residue-name differences within matched sequence blocks, not a comprehensive mutation audit or an independent chain-quality score.

Resolved_controls contains 621 random resolved windows of length 6–15 residues (three per system). These windows use the same sampled frames and reference approach, with the selected window excluded from the fitting core. They are a descriptive comparison, not controls matched to every inferred segment by length, location or exposure. The original control output did not log window residue ranges or chain identifiers; retained source code and frozen results document the available provenance.

Files: Supplementary_Data_S8_grafted_segments.csv; Supplementary_Data_S8_resolved_controls.csv; Supplementary_Data_S8_system_qc.csv; Supplementary_Data_S8_sensitivity.csv; Supplementary_Data_S8_recovered_segments.json; Supplementary_Data_S8_grafted_segments.xlsx. XLSX sheets contain the same tables plus this README. Fields rmsd_mean/rmsd_max/rmsd_last100ns_mean are scaffold-fit statistics; selffit_rmsd_mean/selffit_rmsd_max are segment self-fit statistics. n_frames is the sampled-frame count. error in System_QC is blank for all 207 successful runs. gpcr_class was added from the cohort master in the source summary.
'''
    for name,table in [('grafted_segments',d),('resolved_controls',controls),('system_qc',logs),('sensitivity',sensitivity)]:table.to_csv(data/f'Supplementary_Data_S8_{name}.csv',index=False)
    shutil.copy2(snap/'grafted_segments_recovered_v2.json',data/'Supplementary_Data_S8_recovered_segments.json')
    (data/'Supplementary_Data_S8_README.md').write_text(readme)
    with pd.ExcelWriter(data/'Supplementary_Data_S8_grafted_segments.xlsx') as writer:
        for name,table in [('Segments',d),('Resolved_controls',controls),('System_QC',logs),('Sensitivity',sensitivity)]:table.to_excel(writer,sheet_name=name,index=False)
        pd.DataFrame({'description':readme.split('\n\n')}).to_excel(writer,sheet_name='README',index=False)
    (out/'grafted_verified_numbers.json').write_text(json.dumps(numbers,indent=2))
    return numbers

METHODS='Retrospective validation of modeled regions. Because no original per-system graft log was retained, candidate modeled segments were identified by sequence-aligning each simulated chain against the experimentally resolved residues of its source PDB entry. Uncovered runs separated by up to three matched residues were merged; isolated single residues were excluded from segment statistics. This identifies differences between the simulated and deposited constructs, rather than establishing the provenance of every added coordinate. For replica 1, segment Cα RMSD relative to the production-start structure was sampled at 2-ns intervals over nominal 50–498 ns (225 frames). Frames were fitted on the inferred resolved core of the same chain; six segments with fewer than ten available fitting Cα atoms used a global resolved-core fallback. Segment self-fit RMSD was also measured to distinguish internal conformational change from displacement relative to the scaffold. Supplementary Data S8 provides the per-segment results, fitting scope, chain-match diagnostics, resolved-window controls and filtering sensitivity; Supplementary Note 2 details the protocol and limitations.'
RESULTS='Retrospectively inferred modeled segments. The sequence comparison identified 938 segments of at least two residues across 205 of 207 systems. For 437 short internal loops of at most 20 residues, the median scaffold-fit RMSD was 4.18 Å and 125/437 (28.6%) had a time-averaged RMSD at or below 3 Å. The median segment self-fit RMSD was 1.10 Å, consistent with a contribution from motion relative to the chain scaffold; it does not demonstrate internal rigidity of every segment. Excluding 45 two-residue loops gives a self-fit median of 1.25 Å across 392 loops. The 621 resolved control windows had a scaffold-fit median of 1.98 Å, with 500/621 (81%) at or below 3 Å. Thus, the inferred regions show greater positional mobility than the resolved comparison windows. These results describe replica 1 in the selected analysis window and do not establish modeling accuracy, stationarity or absence of sustained drift (Supplementary Data S8; Supplementary Note 2).'
USAGE='Consult Supplementary Data S8 when an analysis depends on reconstructed regions: inspect segment-specific scaffold-fit and self-fit displacement, fitting scope and sequence correspondence. These retrospective annotations are not a curated graft log. The replica-1 assessment uses a fixed 50-ns exclusion and should be considered alongside the observable-specific stationarity recommendations in S7; it does not establish behavior in replicas 2–3.'
RESPONSE='We have clarified that grafting transfers missing coordinates from an aligned template into the experimentally resolved complex, followed by minimization and equilibration. Using the resolved complex as the framework retains its experimental receptor–G-protein arrangement, rather than replacing that arrangement with a prediction of the entire complex; aligned templates supply the missing regions. No original per-system graft log was retained. We therefore identified candidate modeled segments retrospectively by aligning simulated chains against experimentally resolved source-PDB residues and assessed their motion in replica 1. '+RESULTS.replace('Retrospectively inferred modeled segments. ', '')+' The chain-match score is a length-dependent sequence-similarity ratio, not resolved-residue identity: Gq_8F7X chain A matches all 221 resolved residues within a 351-residue simulated chain, explaining its ratio of 0.773. We retain it and report separate filtering sensitivities in S8 rather than silently changing the population. The SI and S8 document two-residue self-fit limitations and all six global-core fitting fallbacks. Changes: Methods; Data Records; Technical Validation; Usage Notes; Supplementary Note 2; Supplementary Data S8.'
NOTES=[METHODS,
'The frozen v2 computation processed all 207 systems without recorded errors. The inferred mask contains 34,962 residues, including 290 excluded singletons; analyzed segments contain 34,672 residues. The segment categories are 131 N-terminal, 477 internal loops, 236 large inserts, 89 C-terminal and five whole-chain segments. Chain boundaries were inferred from peptide C–N distances above 2.0 Å, with a Cα-distance fallback above 4.2 Å when atoms were unavailable. SequenceMatcher uses all exact matching blocks; it does not require a minimum three-residue block. Source-PDB comparison may differ from comparison against an actual GPCRdb-refined preparation template, and merged segments can include matched bridging residues.',
RESULTS,
'The six global-fit cases are Gq_7S8L, Gq_7SRR, Gq_8DWC and Gq_8E9W (20-residue whole chains), Gs_7TMW (60-residue whole chain), and Gs_7F4H (four-residue N-terminal segment). A same-chain fit removes overall chain motion but retains intrachain domain motion. Self-fitting two Cα atoms is underconstrained and cannot characterize most internal conformational degrees of freedom; both inclusive and at-least-three-residue summaries are reported.',
'The match_ratio diagnostic is 2M/(N_sim + N_exp), where M is the number of sequence matches. Added unresolved sequence lowers this score even for a correct correspondence. Gq_8F7X chain A has 351 simulated residues and 221 resolved residues, all matched, giving 0.773. The full 938-segment population includes its two segments. A sensitivity subset with match_ratio ≥0.9 contains 296 segments across 140 systems, including 143 short loops (median scaffold-fit RMSD 5.07 Å; 22/143, 15%, at or below 3 Å; self-fit median 1.49 Å). Excluding only Gq_8F7X chain A instead gives 936 segments across 204 systems and 436 short loops (scaffold-fit median 4.17 Å; 125/436, 29%, at or below 3 Å; self-fit median 1.11 Å). These subsets are explicitly separated in S8 and do not replace the primary analysis.',
'The resolved-window control uses three randomly selected windows per system, each 6–15 residues long, with the selected window excluded from the fitting core. These are descriptive resolved-fragment controls, without matching to every modeled segment by location or length. The source output did not retain their residue ranges. The 50-ns cutoff is a fixed descriptive choice, not a claim that all trajectories had equilibrated by then. No explicit trend test or additional periodic-boundary rejection was performed in this protocol; aggregate RMSD and last-window means therefore cannot establish absence of sustained drift. Replica-2/3 behavior and accuracy against unavailable experimental coordinates remain outside this assessment.']
